-- Query: select_receive_request_update
-- Type: SELECT

PARAMETERS [p_manufacturing_plant_name] Text(255), [p_from_date] DateTime, [p_until_date] DateTime;
SELECT tut.id AS update_request_id, tut.requested_at AS update_request_date, tut.requested_by AS update_request_by, tut.original_transaction_id, ot.uuid AS old_transaction_uuid, ot.actived_at AS old_transaction_actived_at, ot.reversed_at AS old_transaction_reversed_at, old_r.id AS old_receive_id, old_r.arrival_date AS old_arrival_date, old_r.verification_date AS old_verification_date, old_r.total_receive_amount AS old_total_receive_amount, old_r.ok_amount AS old_ok_amount, old_r.not_ok_amount AS old_not_ok_amount, old_r.remarks AS old_remarks, old_r.system_remarks AS old_system_remarks, old_r.person_in_charge AS old_pic, old_ot.uuid AS old_order_transaction_uuid, old_o.id AS old_order_id, old_o.po_id AS old_order_poid, old_o.order_date AS old_order_date, old_o.amount AS old_order_amount, old_v.name AS old_vendor_name, old_c.name AS old_catalogue_name, old_c.unit_of_measurement AS old_unit_of_measurement, old_mp.name AS old_manufacturing_plant_name, tut.proposed_transaction_id, pt.uuid AS new_transaction_uuid, pt.actived_at AS new_transaction_actived_at, pt.reversed_at AS new_transaction_reversed_at, new_r.id AS new_receive_id, new_r.arrival_date AS new_arrival_date, new_r.verification_date AS new_verification_date, new_r.total_receive_amount AS new_total_receive_amount, new_r.ok_amount AS new_ok_amount, new_r.not_ok_amount AS new_not_ok_amount, new_r.remarks AS new_remarks, new_r.system_remarks AS new_system_remarks, new_r.person_in_charge AS new_pic, new_ot.uuid AS new_order_transaction_uuid, new_o.id AS new_order_id, new_o.po_id AS new_order_poid, new_o.order_date AS new_order_date, new_o.amount AS new_order_amount, new_v.name AS new_vendor_name, new_c.name AS new_catalogue_name, new_c.unit_of_measurement AS new_unit_of_measurement, new_mp.name AS new_manufacturing_plant_name
FROM (((((((((((((transaction_update_requests AS tut INNER JOIN transactions AS ot ON tut.original_transaction_id = ot.id) INNER JOIN transactions AS pt ON tut.proposed_transaction_id = pt.id) INNER JOIN receives AS old_r ON old_r.transaction_id = ot.id) INNER JOIN receives AS new_r ON new_r.transaction_id = pt.id) INNER JOIN orders AS old_o ON old_r.order_id = old_o.id) INNER JOIN orders AS new_o ON new_r.order_id = new_o.id) INNER JOIN transactions AS old_ot ON old_o.transaction_id = old_ot.id) INNER JOIN transactions AS new_ot ON new_o.transaction_id = new_ot.id) INNER JOIN vendors AS old_v ON old_o.vendor_id = old_v.id) INNER JOIN vendors AS new_v ON new_o.vendor_id = new_v.id) INNER JOIN catalogues AS old_c ON old_o.catalogue_id = old_c.id) INNER JOIN catalogues AS new_c ON new_o.catalogue_id = new_c.id) INNER JOIN manufacturing_plants AS old_mp ON old_o.manufacturing_plant_id = old_mp.id) INNER JOIN manufacturing_plants AS new_mp ON new_o.manufacturing_plant_id = new_mp.id
WHERE old_mp.name = [p_manufacturing_plant_name]

    AND old_r.arrival_date >= [p_from_date]

    AND old_r.arrival_date <
        DateAdd("d", 1, [p_until_date])

    AND tut.approved_at IS NULL
ORDER BY tut.requested_at, ot.uuid;
